import { MeshStandardNodeMaterial, PlaneGeometry, BoxGeometry, Mesh, Group } from 'three/webgpu';
import { uv, mix, color, float, vec3 } from 'three/tsl';
import { gsap } from 'gsap';
import { parallaxScroll } from '@/primitives';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();

  // ---------- BACKDROP ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const gradStops = (config.colors?.gradientStops) || [
    { at: 0, hex: '#0b0b10' },
    { at: 1, hex: '#12121a' },
  ];
  const gradColorA = color(gradStops[0].hex);
  const gradColorB = color(gradStops[1].hex);
  const gradNode = mix(gradColorA, gradColorB, uv().y);
  const backdropMat = new MeshStandardNodeMaterial();
  backdropMat.colorNode = gradNode;
  backdropMat.side = THREE.DoubleSide;
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;
  root.add(backdrop);

  // ---------- TEXT ----------
  const headline = ctx.fontAtlas.createText('The collection', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'left',
  });
  headline.position.set(-2.6, 1.5, 0);
  root.add(headline);

  const body = ctx.fontAtlas.createText('Five calibres. One discipline.', {
    fontSize: 26,
    color: '#e8ecf2',
    align: 'left',
  });
  body.position.set(-2.6, -1.5, 0);
  root.add(body);

  // ---------- CARD SETUP ----------
  const cardCount = 5;
  const cardWidth = 1.6;
  const cardHeight = 1.0;
  const cardDepth = 0.02;
  const pitch = 1.85;
  const bevelSize = 0.025;
  const inkColor = '#16161d';
  const accentColor = '#ff2a38';
  const textureUrl = config.imageUrl || '/prism-mock/home/nodes/parallax-stack.png';

  const cardGroup = new Group();
  root.add(cardGroup);

  const textures = [];
  const cardMeshes = [];
  const underlineMeshes = [];
  const captionTexts = [];

  const loadTexPromise = ctx.textureLoader.loadTexture(textureUrl).then((tex) => {
    textures.push(tex);
  });

  for (let i = 0; i < cardCount; i++) {
    const cardRoot = new Group();
    const xPos = (i - Math.floor(cardCount / 2)) * pitch;
    cardRoot.position.x = xPos;
    cardRoot.rotation.y = THREE.MathUtils.degToRad(-18);
    cardGroup.add(cardRoot);

    // Frame (bevel)
    const frameGeom = new BoxGeometry(cardWidth + bevelSize * 2, cardHeight + bevelSize * 2, cardDepth + bevelSize * 2);
    const frameMat = new MeshStandardNodeMaterial({ color: inkColor });
    const frameMesh = new Mesh(frameGeom, frameMat);
    cardRoot.add(frameMesh);

    // Card face
    const cardGeom = new BoxGeometry(cardWidth, cardHeight, cardDepth);
    const cardMat = new MeshStandardNodeMaterial({
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      transparent: true,
      opacity: i === Math.floor(cardCount / 2) ? 1 : 0.55,
    });
    const cardMesh = new Mesh(cardGeom, cardMat);
    cardRoot.add(cardMesh);
    cardMeshes.push(cardMesh);

    // Underline for focused card
    if (i === Math.floor(cardCount / 2)) {
      const underlineGeom = new PlaneGeometry(cardWidth, 0.035);
      const underlineMat = new MeshStandardNodeMaterial({
        color: accentColor,
        emissive: accentColor,
        emissiveIntensity: 1.3,
      });
      const underline = new Mesh(underlineGeom, underlineMat);
      underline.position.set(0, -cardHeight / 2 - 0.07, 0);
      cardRoot.add(underline);
      underlineMeshes.push(underline);
    }

    // Caption text
    const captions = [
      'NA-01 MERIDIAN',
      'NA-02 NOCTURNE',
      'NA-03 SIGNAL',
      'NA-04 VANTAGE',
      'NA-05 ARCHIVE',
    ];
    const caption = ctx.fontAtlas.createText(captions[i], {
      fontSize: 18,
      color: '#e8ecf2',
      align: 'center',
    });
    caption.position.set(0, -cardHeight / 2 - 0.15, 0);
    cardRoot.add(caption);
    captionTexts.push(caption);
  }

  // Apply texture when loaded
  loadTexPromise.then(() => {
    const tex = textures[0];
    cardMeshes.forEach((mesh) => {
      mesh.material.map = tex;
      mesh.material.needsUpdate = true;
    });
  });

  // ---------- PRIMITIVE ----------
  const primitives = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const name = prim.name;
      const params = prim.params || {};
      const trigger = prim.trigger;
      const p = ctx.primitives[name](root, { ...params, trigger });
      primitives.push(p);
    });
  }

  // ---------- CLEANUP ----------
  root.userData.cleanup = () => {
    // Dispose geometries and materials
    backdropGeom.dispose();
    backdropMat.dispose();
    cardMeshes.forEach((m) => {
      m.geometry.dispose();
      m.material.dispose();
    });
    underlineMeshes.forEach((m) => {
      m.geometry.dispose();
      m.material.dispose();
    });
    // Text objects cleanup (if any)
    [headline, body, ...captionTexts].forEach((txt) => {
      if (txt && txt.geometry && txt.geometry.dispose) txt.geometry.dispose();
    });
    // Cleanup primitives
    primitives.forEach((p) => {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    });
    // Kill GSAP timelines if any
    gsap.globalTimeline.clear();
  };

  // No interaction handlers required
  root.userData.handlers = {};

  return root;
}
